def cohen_r_label(r):
    r = abs(r)
    if r >= 0.5:   return "large"
    if r >= 0.3:   return "medium"
    if r >= 0.1:   return "small"
    return "negligible"


def cohen_f2_label(f2, df_resid=None):
    if f2 is None: return "N/A"
    if df_resid is not None and df_resid < 20:
        return "df_too_low"
    if f2 >= 0.35: return "large"
    if f2 >= 0.15: return "medium"
    if f2 >= 0.02: return "small"
    return "negligible"


def adf_order(series, max_d=2):
    for d in range(max_d + 1):
        s = series.copy()
        for _ in range(d):
            s = np.diff(s)
        if len(s) < 5:
            return d
        try:
            if adfuller(s, maxlag=1, autolag=None)[1] < 0.05:
                return d
        except Exception:
            pass
    return max_d


